const raw = $input.first().json || {};
const src = Object.assign({}, raw.body || {}, raw.query || {}, raw);
const v = (k) => { const x = src[k]; return x == null ? '' : String(x).trim(); };
const content = v('CONTENT');
if (!content) throw new Error('CONTENT is required');
// FORCE pins the form; STYLE names a brand scheme and is resolved (and defaulted)
// in brand_tokens, where the scheme names live, so an unknown value fails there.
const FORCES = ['auto', 'diagram', 'story', 'data', 'poster', 'code', 'chart', 'timeline', 'quote', 'ui', 'manga'];
const force = v('FORCE') || 'auto';
if (!FORCES.includes(force)) throw new Error('unknown FORCE: ' + force + ' (expected one of ' + FORCES.join(', ') + ')');
// An optional scene plan: a list-shaped article asks for one item per scene. A blank
// or non-positive value leaves the scene count to the composer's own storyboard.
const scenesRaw = parseInt(v('SCENES'), 10);
const scenes = (isFinite(scenesRaw) && scenesRaw > 0) ? Math.min(scenesRaw, 12) : '';
return [{ json: {
  RUN_ID: String($execution.id),
  CONTENT: content,
  ASSET_TYPES: v('ASSET_TYPES'),
  FEEDBACK: v('FEEDBACK'),
  // Free text the caller owns, appended to the brief after the content and the
  // rules. Never parsed.
  EXTRA_PROMPT: v('EXTRA_PROMPT'),
  // A session to continue, when the caller names one. Blank means this run is a
  // first authoring, with an identifier scoped to the run so it stays isolated.
  SESSION_ID: v('SESSION_ID'),
  FORCE: force,
  SCENES: scenes,
  STYLE: v('STYLE'),
} }];

const cfg = JSON.parse($('download_registry').first().json.output || '{}');
const req = $('normalize_input').first().json;
const types = Array.isArray(cfg.types) ? cfg.types : [];
const byId = new Map(types.map((t) => [t.id, t]));
const budget = cfg.budget || {};
const cap = Number(cfg.max_types_per_request || 3);
let requested = req.ASSET_TYPES
  ? req.ASSET_TYPES.split(',').map((s) => s.trim()).filter(Boolean)
  : (cfg.default_types || []);
requested = [...new Set(requested)];
const out = [];
const shaped = (t, extra) => {
  const b = Object.assign({}, budget, t.budget || {});
  const paired = t.paired || {};
  return Object.assign({}, req, {
    ASSET_TYPE: t.id, NAME: t.name || t.id, AUTHOR: t.author, BRAND_KIND: t.brandKind || 'diagrammatic',
    RENDER_MODE: t.render, FORMAT: t.format, ASPECT: t.aspect || '4:5',
    FPS: Number(b.fps || 12), FRAMES: Number(b.frames || 36), VIEWPORT: Number(b.viewport || 1200),
    DURATION_SECONDS: Number(t.durationSeconds || 0),
    SCENE_SECONDS: Number(t.secondsPerScene || 0),
    PAIRED_FORMAT: paired.format || '', PAIRED_ASSET_TYPE: paired.assetType || '',
  }, extra);
};
const note = (id, status, error) => out.push({ json: Object.assign({}, req, {
  ASSET_TYPE: id, NAME: id, AUTHOR: null, BRAND_KIND: '', RENDER_MODE: '', FORMAT: '', ASPECT: '',
  FPS: 0, FRAMES: 0, VIEWPORT: 0, DURATION_SECONDS: 0, STATUS: status, ERROR: error }) });
for (const id of requested.slice(0, cap)) {
  const t = byId.get(id);
  if (!t) { note(id, 'UNKNOWN', 'unknown asset type: ' + id); continue; }
  const kind = t.brandKind || 'diagrammatic';
  if (kind !== 'diagrammatic' && kind !== 'photographic') throw new Error('unknown brandKind for ' + t.id + ': ' + t.brandKind);
  // An unavailable type must not take its author branch: null its author so it
  // falls through to the report path with a STATUS and reason.
  if (t.available === false) {
    out.push({ json: shaped(t, { AUTHOR: null, STATUS: 'UNAVAILABLE', ERROR: t.unavailableReason || ('unavailable: ' + t.id) }) });
    continue;
  }
  out.push({ json: shaped(t, { STATUS: '' }) });
}
for (const id of requested.slice(cap)) note(id, 'SKIPPED', 'over the per-request cap of ' + cap);
return out;

const src = $('if_raster').all();
const dir = $('raster_director').all();
return $input.all().map((it, i) => {
  const a = src[i].json;
  const resp = it.json || {};
  const d0 = (resp.data && resp.data[0]) || {};
  const b64 = d0.b64_json || '';
  const media = d0.media_type || 'image/png';
  const out = Object.assign({}, a, {
    STATUS: b64 ? 'RENDERED' : 'ERROR',
    PROMPT: (dir[i] && dir[i].json.text) || '',
    IMAGE: b64 ? ('data:' + media + ';base64,' + b64) : '',
    CONTENT_TYPE: b64 ? media : '',
  });
  if (!b64) out.ERROR = 'image model returned no image';
  return { json: out };
});

// The run row. RESULT carries each asset's STORYBOARD and the object key its bytes were
// written to, never the bytes themselves: the artifact is a base64 data URL, and four
// such rows filled visual_studio_table to its 200 MB cap on 2026-10-13, which failed
// every later run at record_run. The response is built by set_result from merge_branches,
// so the caller still receives the asset itself.
const items = $('merge_branches').all().map((i) => i.json);
const req = $('normalize_input').first().json;
const brand = $('brand_tokens').first().json;
const stored = new Map();
try {
  for (const i of $('prepare_uploads').all()) {
    if (i.json && i.json.S3_KEY) stored.set(i.json.ASSET_TYPE, i.json);
  }
} catch (e) {
  // upload_assets is skipped when there was nothing to store, which is a legitimate
  // run: the assets still report their own ERROR below.
}
const errors = items.filter((i) => i.ERROR).map((i) => i.ASSET_TYPE + ': ' + i.ERROR);
const slim = items.map((a) => {
  const s = stored.get(a.ASSET_TYPE) || {};
  return Object.assign({}, a, { IMAGE: '', S3_KEY: s.S3_KEY || '', S3_BYTES: s.S3_BYTES || 0 });
});
return [{ json: {
  RUN_ID: req.RUN_ID,
  STATUS: errors.length === 0 ? 'COMPLETE' : (items.some((i) => !i.ERROR) ? 'PARTIAL' : 'FAILED'),
  REQUEST: JSON.stringify({ ASSET_TYPES: req.ASSET_TYPES, FORCE: req.FORCE, STYLE: brand.STYLE,
                            FEEDBACK: req.FEEDBACK, EXTRA_PROMPT: req.EXTRA_PROMPT,
                            SESSION_ID: req.SESSION_ID, CONTENT_LENGTH: req.CONTENT.length }),
  RESULT: JSON.stringify(slim),
  ASSET_COUNT: String(items.length),
  ERROR: errors.join(' | ').slice(0, 2000),
} }];

const items = $('merge_branches').all().map((i) => i.json);
const req = $('normalize_input').first().json;
return [{ json: {
  RUN_ID: req.RUN_ID,
  STATUS: items.some((i) => i.ERROR) ? (items.every((i) => i.ERROR) ? 'FAILED' : 'PARTIAL') : 'COMPLETE',
  ASSETS: items,
} }];

// Turn the request into the composer's brief and the session request. The brief is
// the caller's CONTENT, the requested form and style, the type's declared frame, the
// shared motion rules and any correction or extra direction the caller supplied.
// A caller that names a session continues it - the composer edits the composition
// that session already holds - and a caller that names none gets an id scoped to
// this run, so a later run cannot overwrite its artifact before it is fetched.
// Everything here is data-driven, so a type is retuned from the registry without
// touching the adapter.
const a = $input.first().json;
const req = $('normalize_input').first().json;
const brand = $('brand_tokens').first().json;
const rules = String($('visual_rules').first().json.RULES || '').trim();
const safe = (s) => String(s || '').replace(/[^A-Za-z0-9._-]/g, '').slice(0, 40);
// A named session is continued as given; a blank one is scoped to this run.
const sessionId = safe(req.SESSION_ID) || (safe(a.ASSET_TYPE) + '-' + safe(req.RUN_ID)) || 'default';
const isIteration = Boolean(String(req.SESSION_ID || '').trim());
const base = ($env.PI_RENDER_URL || '').replace(/\/+$/, '');
// A deck is authored as one self-contained HTML file; the same turn renders it to
// the paired video, so no transcode happens after the turn.
const isDeck = String(a.RENDER_MODE || '') === 'deck';
const FORMATS = ['mp4', 'gif', 'webp', 'png', 'svg'];
const format = isDeck ? 'html' : (FORMATS.includes(a.FORMAT) ? a.FORMAT : 'mp4');
const [aw, ah] = String(a.ASPECT || '4:5').split(':').map(Number);
const width = Math.max(1, Number(a.VIEWPORT) || 1080);
const height = Math.round(width * (ah || 5) / (aw || 4));
const force = String(req.FORCE || 'auto');
// The form vocabulary is one committed file, fetched like the motion rules and
// appended to the brief so a forced form arrives with its meaning; the workflow does
// not restate the definitions.
const forms = String($('visual_forms').first().json.FORMS || '').trim();
const vocab = forms ? ['Form vocabulary:', forms] : [];
const form = force === 'auto'
  ? 'Choose the form that fits the content best.'
  : 'Use the ' + force + ' form; do not substitute another.';
const scenes = Math.max(0, Math.round(Number(req.SCENES) || 0));
// One declared scene is the whole clip. A longer sequence opens on a title scene
// that names the subject, so it is introduced rather than starting cold; the
// caller's scenes follow it, and the clip carries one more scene than was asked.
const sceneLine = scenes > 0
  ? 'Render exactly ' + scenes + ' scenes, one item per scene, in the order the storyboard sets'
    + (scenes > 1 ? ', opening on a title scene that names the subject before them (' + (scenes + 1) + ' scenes in all).' : '.')
  : '';
// The declared duration is the floor. A caller that names a scene count gives each
// scene at least the type's declared scene length, so a multi-scene clip is never
// compressed into the single-scene time.
const declaredFrames = Math.max(1, Number(a.FRAMES) || 24);
const declaredSeconds = Math.max(1, Number(a.DURATION_SECONDS) || Math.round(declaredFrames / Math.max(1, Number(a.FPS) || 8)));
const sceneSeconds = Math.max(0, Number(a.SCENE_SECONDS) || 0);
const seconds = Math.max(declaredSeconds, scenes * sceneSeconds);
// Extending the clip keeps the declared sampling rate instead of speeding it up.
const frames = seconds > declaredSeconds ? Math.max(1, Math.round(declaredFrames * seconds / declaredSeconds)) : declaredFrames;
const rate = Math.max(0.1, frames / seconds);
// A continuation keeps the composition the session already holds and applies only
// the change below; a first authoring plans before it builds.
const opening = isIteration
  ? ['This continues the composition already in this session: apply the change below to it and keep everything else.']
  : [];
const planLine = 'Plan first: state a short storyboard with the form, the scenes and the order they play in, then author the composition.';
const deckPlanLine = 'Plan first: state a short plan with the arc and the per-slide content, then author the deck to it.';
const sampling = ['gif', 'webp'].includes(format)
  ? 'Animate slowly and deliberately: reveal a few elements in sequence, each held long enough to read, rather than many quick changes. The clip is sampled into a low-frame-rate file, so fast or busy motion is lost.'
  : 'Animate deliberately: a few clear beats, each held long enough to read, rather than many quick changes.';
const styleLine = 'Style: use the brand\'s ' + brand.STYLE + ' scheme; do not introduce a colour or typeface the brand block below does not define.';
// Appended last, in this order: the shared motion rules (the framework's craft, one
// committed copy), a reviewer's correction when one is present, and the caller's
// extra direction when one is present. Nothing here is parsed; all three are prose
// the composer reads.
const tail = [];
if (rules) tail.push('Motion rules (apply to every scene):', rules);
if (req.FEEDBACK) tail.push('Correction from a reviewer - fix this in this attempt:', req.FEEDBACK);
if (req.EXTRA_PROMPT) tail.push('Extra direction from the caller:', req.EXTRA_PROMPT);
const brandBlock = ['', 'Brand block:', brand.BRAND];
const brief = isDeck
  ? [
      req.CONTENT,
      '',
      ...(isIteration ? opening : [deckPlanLine]),
      sceneLine,
      'Author ONE self-contained HTML presentation and write it to `out.html` in this directory: a single file with no external stylesheet, script, font or network request, whose navigation works with no server. Preserve the text\'s own structure, one idea per slide.',
      'Then author a HyperFrames composition of that same plan to `index.html` and render it to `out.mp4` in this same directory, at ' + width + 'x' + height + ' (' + (a.ASPECT || '16:9') + ') over about ' + seconds + ' seconds, so the slides and their order match the deck.',
      styleLine,
      ...tail,
      ...brandBlock,
    ].join('\n')
  : format === 'svg'
  ? [
      req.CONTENT,
      '',
      'Author ONE self-contained animated SVG and write it to `out.svg`. Do not render and do not write index.html.',
      ...opening,
      form,
      ...vocab,
      sceneLine,
      styleLine,
      'Use a ' + width + 'x' + height + ' (' + (a.ASPECT || '4:5') + ') viewBox.',
      'Animate with CSS @keyframes inside a <style> element, or with SMIL; no external stylesheet, no script, no network. Reveal a few elements in sequence, each held long enough to read.',
      'Reference the brand typefaces by name with a system fallback, and keep the file well-formed XML with every animated element ending visible.',
      ...tail,
      ...brandBlock,
    ].join('\n')
  : [
      req.CONTENT,
      '',
      ...(isIteration ? opening : [planLine]),
      form,
      ...vocab,
      sceneLine,
      styleLine,
      'Render a ' + width + 'x' + height + ' (' + (a.ASPECT || '4:5') + ') composition that runs about ' + seconds + ' seconds.',
      sampling,
      ...tail,
      ...brandBlock,
    ].join('\n');
const pairedFormat = isDeck ? (a.PAIRED_FORMAT || 'mp4') : '';
return [{ json: Object.assign({}, a, {
  FORCE: force, SCENES: scenes, STYLE: brand.STYLE,
  FORMAT: format, FPS: rate, WIDTH: width, HEIGHT: height, FRAMES: frames, DURATION_SECONDS: seconds, RATE: rate,
  SESSION_ID: sessionId,
  AUTHOR_URL: base ? base + '/v1/chat/completions' : '',
  ARTIFACT_URL: base ? base + '/artifacts/' + sessionId + '/out.' + format : '',
  PAIRED_FORMAT: pairedFormat,
  PAIRED_ARTIFACT_URL: (isDeck && base) ? base + '/artifacts/' + sessionId + '/out.' + pairedFormat : '',
  AUTHOR_BODY: JSON.stringify({ messages: [{ role: 'user', content: brief }], session_id: sessionId, format: format, fps: rate, width: width, frames: frames, durationSeconds: seconds }),
}) }];

// The rendered artifact the session returned, as the asset, plus the composer's own
// report kept as STORYBOARD so a bad visual is diagnosable from the run record. Read
// the bytes with getBinaryDataBuffer: this instance keeps binaries out of band, so
// binary.data is a reference ("database:<id>"), not the base64. The workflow never
// sees the agent's composition markup, only this file. A deck run yields two files
// in one turn - the deck and its paired video - so it returns two assets.
const a = $('build_author_brief').first().json;
const item = $input.first();
const out = item.json || {};
const binMeta = (item.binary && item.binary.data) || null;
const report = (() => {
  try {
    const resp = $('execute_author').first().json || {};
    const msg = resp.choices && resp.choices[0] && resp.choices[0].message;
    const content = msg && msg.content;
    return typeof content === 'string' ? content.slice(0, 6000) : '';
  } catch (e) { return ''; }
})();
const base = {
  ASSET_TYPE: a.ASSET_TYPE, RENDER_MODE: a.RENDER_MODE || '', FORMAT: a.FORMAT || '',
  STATUS: '', PROMPT: '', CONTENT_TYPE: '', ERROR: '', STORYBOARD: report,
  DURATION_MS: String(Math.round((Number(a.DURATION_SECONDS) || 0) * 1000)),
  FRAME_COUNT: String(Number(a.FRAMES) || ''), WIDTH: a.WIDTH || '', HEIGHT: a.HEIGHT || '',
  IMAGE: '',
};
const describe = (v, fallback) => {
  if (typeof v === 'string' && v) return v;
  if (v && typeof v === 'object' && typeof v.message === 'string') return v.message;
  if (v != null) return JSON.stringify(v);
  return fallback;
};
if (!a.AUTHOR_URL) {
  return [{ json: Object.assign({}, base, { STATUS: 'ERROR', ERROR: 'PI_RENDER_URL is not configured' }) }];
}
if (!binMeta) {
  const reason = describe(out.error || out.message, 'agent authoring returned no artifact').slice(0, 500);
  return [{ json: Object.assign({}, base, { STATUS: 'ERROR', ERROR: reason }) }];
}
const mime = binMeta.mimeType || 'image/gif';
const buffer = await this.helpers.getBinaryDataBuffer(0, 'data');
const items = [Object.assign({}, base, {
  STATUS: 'RENDERED', CONTENT_TYPE: mime, IMAGE: 'data:' + mime + ';base64,' + buffer.toString('base64'),
})];
// A deck's paired video arrives on the same item as `paired`, fetched after the deck.
const pairedMeta = item.binary && item.binary.paired;
if (pairedMeta) {
  const pairedMime = pairedMeta.mimeType || 'video/mp4';
  const pairedBuffer = await this.helpers.getBinaryDataBuffer(0, 'paired');
  items.push(Object.assign({}, base, {
    ASSET_TYPE: a.PAIRED_ASSET_TYPE || (a.ASSET_TYPE + '_video'),
    RENDER_MODE: 'video', FORMAT: a.PAIRED_FORMAT || 'mp4', PAIRED_OF: a.ASSET_TYPE,
    STATUS: 'RENDERED', CONTENT_TYPE: pairedMime,
    IMAGE: 'data:' + pairedMime + ';base64,' + pairedBuffer.toString('base64'),
  }));
}
return items.map((json) => ({ json }));

// The brand, read once from datasets/brand.json (the only copy), resolved to the
// requested scheme and shaped for its two consumers: the authoring brief for the
// composer and the raster prompt. This node also owns the STYLE check, because the
// scheme names are data here and nowhere else, so an unknown STYLE fails naming it.
const raw = $('download_brand').first().json.output || '{}';
let b;
try {
  b = JSON.parse(raw);
} catch (e) {
  throw new Error('datasets/brand.json is not valid JSON: ' + e.message);
}
const req = $('normalize_input').first().json;
const schemeName = String(req.STYLE || b.defaultScheme || '');
const scheme = b.schemes && b.schemes[schemeName];
if (!scheme) throw new Error('unknown STYLE: ' + schemeName + ' (brand declares: ' + Object.keys(b.schemes || {}).join(', ') + ')');
const typo = b.typography || {};
const BRAND = [
  'Brand palette (' + schemeName + ' scheme, use only these roles):',
  'background ' + scheme.shell + ', text ' + scheme.ink + ', muted text ' + scheme.inkMuted + ',',
  'accent ' + scheme.accent + ', accent-strong ' + scheme.accentStrong + ', accent-deep ' + scheme.accentDeep + '.',
  'Typefaces: ' + typo.text + ' for text, ' + typo.code + ' for code.',
].join('\n');
return [{ json: {
  STYLE: schemeName,
  BRAND,
  ART_DIRECTION: String((b.photographic || {}).artDirection || ''),
} }];

// prompts/visual_motion_rules.md is the one copy of the motion grammar. It is
// fetched once and handed to build_author_brief, which appends it to every brief.
return [{ json: { RULES: String($json.output || '') } }];

// prompts/visual_forms.md is the one copy of the form vocabulary. It is fetched
// once and handed to build_author_brief, which appends it to every brief.
return [{ json: { FORMS: String($json.output || '') } }];

// One item per rendered asset, with the base64 data URL turned into binary so the S3
// node can upload it, and the object key the run row will carry instead of the bytes.
// The prune lists the prefix 'visual-studio/' and the S3 node's file:getAll sets a '/'
// delimiter, so the key must not add another one: with the prefix left as
// 'visual-studio' the key's own slash makes it a CommonPrefix and it is never listed.
// A run where every asset failed has nothing to store and returns none.
const items = $('merge_branches').all().map((i) => i.json);
const runId = String($('normalize_input').first().json.RUN_ID || '').replace(/[^A-Za-z0-9_-]/g, '');
const EXT = { 'video/mp4': 'mp4', 'image/gif': 'gif', 'image/webp': 'webp', 'image/png': 'png',
              'image/svg+xml': 'svg', 'text/html': 'html' };
const out = [];
for (const a of items) {
  const url = String(a.IMAGE || '');
  const comma = url.indexOf(',');
  if (!url.startsWith('data:') || comma < 0) continue;
  const mime = url.slice(5, url.indexOf(';', 5));
  const ext = EXT[mime] || 'bin';
  const name = String(a.ASSET_TYPE || 'asset').replace(/[^A-Za-z0-9._-]/g, '');
  const key = 'visual-studio/' + runId + '-' + name + '.' + ext;
  const buffer = Buffer.from(url.slice(comma + 1), 'base64');
  out.push({
    json: { S3_KEY: key, S3_BYTES: buffer.length, CONTENT_TYPE: mime, ASSET_TYPE: a.ASSET_TYPE },
    binary: { data: await this.helpers.prepareBinaryData(buffer, key, mime) },
  });
}
return out;

const raw = $input.first().json || {};
const src = Object.assign({}, raw.body || {}, raw.query || {}, raw);
const v = (k) => { const x = src[k]; return x == null ? '' : String(x).trim(); };
const content = v('CONTENT');
if (!content) throw new Error('CONTENT is required');
// FORCE pins the form; STYLE names a brand scheme and is resolved (and defaulted)
// in brand_tokens, where the scheme names live, so an unknown value fails there.
const FORCES = ['auto', 'diagram', 'story', 'data', 'poster', 'code', 'chart', 'timeline', 'quote', 'ui', 'manga'];
const force = v('FORCE') || 'auto';
if (!FORCES.includes(force)) throw new Error('unknown FORCE: ' + force + ' (expected one of ' + FORCES.join(', ') + ')');
// An optional scene plan: a list-shaped article asks for one item per scene. A blank
// or non-positive value leaves the scene count to the composer's own storyboard.
const scenesRaw = parseInt(v('SCENES'), 10);
const scenes = (isFinite(scenesRaw) && scenesRaw > 0) ? Math.min(scenesRaw, 12) : '';
return [{ json: {
  RUN_ID: String($execution.id),
  CONTENT: content,
  ASSET_TYPES: v('ASSET_TYPES'),
  FEEDBACK: v('FEEDBACK'),
  // Free text the caller owns, appended to the brief after the content and the
  // rules. Never parsed.
  EXTRA_PROMPT: v('EXTRA_PROMPT'),
  // A session to continue, when the caller names one. Blank means this run is a
  // first authoring, with an identifier scoped to the run so it stays isolated.
  SESSION_ID: v('SESSION_ID'),
  FORCE: force,
  SCENES: scenes,
  STYLE: v('STYLE'),
} }];

const cfg = JSON.parse($('download_registry').first().json.output || '{}');
const req = $('normalize_input').first().json;
const types = Array.isArray(cfg.types) ? cfg.types : [];
const byId = new Map(types.map((t) => [t.id, t]));
const budget = cfg.budget || {};
const cap = Number(cfg.max_types_per_request || 3);
let requested = req.ASSET_TYPES
  ? req.ASSET_TYPES.split(',').map((s) => s.trim()).filter(Boolean)
  : (cfg.default_types || []);
requested = [...new Set(requested)];
const out = [];
const shaped = (t, extra) => {
  const b = Object.assign({}, budget, t.budget || {});
  const paired = t.paired || {};
  return Object.assign({}, req, {
    ASSET_TYPE: t.id, NAME: t.name || t.id, AUTHOR: t.author, BRAND_KIND: t.brandKind || 'diagrammatic',
    RENDER_MODE: t.render, FORMAT: t.format, ASPECT: t.aspect || '4:5',
    FPS: Number(b.fps || 12), FRAMES: Number(b.frames || 36), VIEWPORT: Number(b.viewport || 1200),
    DURATION_SECONDS: Number(t.durationSeconds || 0),
    SCENE_SECONDS: Number(t.secondsPerScene || 0),
    PAIRED_FORMAT: paired.format || '', PAIRED_ASSET_TYPE: paired.assetType || '',
  }, extra);
};
const note = (id, status, error) => out.push({ json: Object.assign({}, req, {
  ASSET_TYPE: id, NAME: id, AUTHOR: null, BRAND_KIND: '', RENDER_MODE: '', FORMAT: '', ASPECT: '',
  FPS: 0, FRAMES: 0, VIEWPORT: 0, DURATION_SECONDS: 0, STATUS: status, ERROR: error }) });
for (const id of requested.slice(0, cap)) {
  const t = byId.get(id);
  if (!t) { note(id, 'UNKNOWN', 'unknown asset type: ' + id); continue; }
  const kind = t.brandKind || 'diagrammatic';
  if (kind !== 'diagrammatic' && kind !== 'photographic') throw new Error('unknown brandKind for ' + t.id + ': ' + t.brandKind);
  // An unavailable type must not take its author branch: null its author so it
  // falls through to the report path with a STATUS and reason.
  if (t.available === false) {
    out.push({ json: shaped(t, { AUTHOR: null, STATUS: 'UNAVAILABLE', ERROR: t.unavailableReason || ('unavailable: ' + t.id) }) });
    continue;
  }
  out.push({ json: shaped(t, { STATUS: '' }) });
}
for (const id of requested.slice(cap)) note(id, 'SKIPPED', 'over the per-request cap of ' + cap);
return out;

const src = $('if_raster').all();
const dir = $('raster_director').all();
return $input.all().map((it, i) => {
  const a = src[i].json;
  const resp = it.json || {};
  const d0 = (resp.data && resp.data[0]) || {};
  const b64 = d0.b64_json || '';
  const media = d0.media_type || 'image/png';
  const out = Object.assign({}, a, {
    STATUS: b64 ? 'RENDERED' : 'ERROR',
    PROMPT: (dir[i] && dir[i].json.text) || '',
    IMAGE: b64 ? ('data:' + media + ';base64,' + b64) : '',
    CONTENT_TYPE: b64 ? media : '',
  });
  if (!b64) out.ERROR = 'image model returned no image';
  return { json: out };
});

// The run row. RESULT carries each asset's STORYBOARD and the object key its bytes were
// written to, never the bytes themselves: the artifact is a base64 data URL, and four
// such rows filled visual_studio_table to its 200 MB cap on 2026-10-13, which failed
// every later run at record_run. The response is built by set_result from merge_branches,
// so the caller still receives the asset itself.
const items = $('merge_branches').all().map((i) => i.json);
const req = $('normalize_input').first().json;
const brand = $('brand_tokens').first().json;
const stored = new Map();
try {
  for (const i of $('prepare_uploads').all()) {
    if (i.json && i.json.S3_KEY) stored.set(i.json.ASSET_TYPE, i.json);
  }
} catch (e) {
  // upload_assets is skipped when there was nothing to store, which is a legitimate
  // run: the assets still report their own ERROR below.
}
const errors = items.filter((i) => i.ERROR).map((i) => i.ASSET_TYPE + ': ' + i.ERROR);
const slim = items.map((a) => {
  const s = stored.get(a.ASSET_TYPE) || {};
  return Object.assign({}, a, { IMAGE: '', S3_KEY: s.S3_KEY || '', S3_BYTES: s.S3_BYTES || 0 });
});
return [{ json: {
  RUN_ID: req.RUN_ID,
  STATUS: errors.length === 0 ? 'COMPLETE' : (items.some((i) => !i.ERROR) ? 'PARTIAL' : 'FAILED'),
  REQUEST: JSON.stringify({ ASSET_TYPES: req.ASSET_TYPES, FORCE: req.FORCE, STYLE: brand.STYLE,
                            FEEDBACK: req.FEEDBACK, EXTRA_PROMPT: req.EXTRA_PROMPT,
                            SESSION_ID: req.SESSION_ID, CONTENT_LENGTH: req.CONTENT.length }),
  RESULT: JSON.stringify(slim),
  ASSET_COUNT: String(items.length),
  ERROR: errors.join(' | ').slice(0, 2000),
} }];

const items = $('merge_branches').all().map((i) => i.json);
const req = $('normalize_input').first().json;
return [{ json: {
  RUN_ID: req.RUN_ID,
  STATUS: items.some((i) => i.ERROR) ? (items.every((i) => i.ERROR) ? 'FAILED' : 'PARTIAL') : 'COMPLETE',
  ASSETS: items,
} }];

// Turn the request into the composer's brief and the session request. The brief is
// the caller's CONTENT, the requested form and style, the type's declared frame, the
// shared motion rules and any correction or extra direction the caller supplied.
// A caller that names a session continues it - the composer edits the composition
// that session already holds - and a caller that names none gets an id scoped to
// this run, so a later run cannot overwrite its artifact before it is fetched.
// Everything here is data-driven, so a type is retuned from the registry without
// touching the adapter.
const a = $input.first().json;
const req = $('normalize_input').first().json;
const brand = $('brand_tokens').first().json;
const rules = String($('visual_rules').first().json.RULES || '').trim();
const safe = (s) => String(s || '').replace(/[^A-Za-z0-9._-]/g, '').slice(0, 40);
// A named session is continued as given; a blank one is scoped to this run.
const sessionId = safe(req.SESSION_ID) || (safe(a.ASSET_TYPE) + '-' + safe(req.RUN_ID)) || 'default';
const isIteration = Boolean(String(req.SESSION_ID || '').trim());
const base = ($env.PI_RENDER_URL || '').replace(/\/+$/, '');
// A deck is authored as one self-contained HTML file; the same turn renders it to
// the paired video, so no transcode happens after the turn.
const isDeck = String(a.RENDER_MODE || '') === 'deck';
const FORMATS = ['mp4', 'gif', 'webp', 'png', 'svg'];
const format = isDeck ? 'html' : (FORMATS.includes(a.FORMAT) ? a.FORMAT : 'mp4');
const [aw, ah] = String(a.ASPECT || '4:5').split(':').map(Number);
const width = Math.max(1, Number(a.VIEWPORT) || 1080);
const height = Math.round(width * (ah || 5) / (aw || 4));
const force = String(req.FORCE || 'auto');
// The form vocabulary is one committed file, fetched like the motion rules and
// appended to the brief so a forced form arrives with its meaning; the workflow does
// not restate the definitions.
const forms = String($('visual_forms').first().json.FORMS || '').trim();
const vocab = forms ? ['Form vocabulary:', forms] : [];
const form = force === 'auto'
  ? 'Choose the form that fits the content best.'
  : 'Use the ' + force + ' form; do not substitute another.';
const scenes = Math.max(0, Math.round(Number(req.SCENES) || 0));
// One declared scene is the whole clip. A longer sequence opens on a title scene
// that names the subject, so it is introduced rather than starting cold; the
// caller's scenes follow it, and the clip carries one more scene than was asked.
const sceneLine = scenes > 0
  ? 'Render exactly ' + scenes + ' scenes, one item per scene, in the order the storyboard sets'
    + (scenes > 1 ? ', opening on a title scene that names the subject before them (' + (scenes + 1) + ' scenes in all).' : '.')
  : '';
// The declared duration is the floor. A caller that names a scene count gives each
// scene at least the type's declared scene length, so a multi-scene clip is never
// compressed into the single-scene time.
const declaredFrames = Math.max(1, Number(a.FRAMES) || 24);
const declaredSeconds = Math.max(1, Number(a.DURATION_SECONDS) || Math.round(declaredFrames / Math.max(1, Number(a.FPS) || 8)));
const sceneSeconds = Math.max(0, Number(a.SCENE_SECONDS) || 0);
const seconds = Math.max(declaredSeconds, scenes * sceneSeconds);
// Extending the clip keeps the declared sampling rate instead of speeding it up.
const frames = seconds > declaredSeconds ? Math.max(1, Math.round(declaredFrames * seconds / declaredSeconds)) : declaredFrames;
const rate = Math.max(0.1, frames / seconds);
// A continuation keeps the composition the session already holds and applies only
// the change below; a first authoring plans before it builds.
const opening = isIteration
  ? ['This continues the composition already in this session: apply the change below to it and keep everything else.']
  : [];
const planLine = 'Plan first: state a short storyboard with the form, the scenes and the order they play in, then author the composition.';
const deckPlanLine = 'Plan first: state a short plan with the arc and the per-slide content, then author the deck to it.';
const sampling = ['gif', 'webp'].includes(format)
  ? 'Animate slowly and deliberately: reveal a few elements in sequence, each held long enough to read, rather than many quick changes. The clip is sampled into a low-frame-rate file, so fast or busy motion is lost.'
  : 'Animate deliberately: a few clear beats, each held long enough to read, rather than many quick changes.';
const styleLine = 'Style: use the brand\'s ' + brand.STYLE + ' scheme; do not introduce a colour or typeface the brand block below does not define.';
// Appended last, in this order: the shared motion rules (the framework's craft, one
// committed copy), a reviewer's correction when one is present, and the caller's
// extra direction when one is present. Nothing here is parsed; all three are prose
// the composer reads.
const tail = [];
if (rules) tail.push('Motion rules (apply to every scene):', rules);
if (req.FEEDBACK) tail.push('Correction from a reviewer - fix this in this attempt:', req.FEEDBACK);
if (req.EXTRA_PROMPT) tail.push('Extra direction from the caller:', req.EXTRA_PROMPT);
const brandBlock = ['', 'Brand block:', brand.BRAND];
const brief = isDeck
  ? [
      req.CONTENT,
      '',
      ...(isIteration ? opening : [deckPlanLine]),
      sceneLine,
      'Author ONE self-contained HTML presentation and write it to `out.html` in this directory: a single file with no external stylesheet, script, font or network request, whose navigation works with no server. Preserve the text\'s own structure, one idea per slide.',
      'Then author a HyperFrames composition of that same plan to `index.html` and render it to `out.mp4` in this same directory, at ' + width + 'x' + height + ' (' + (a.ASPECT || '16:9') + ') over about ' + seconds + ' seconds, so the slides and their order match the deck.',
      styleLine,
      ...tail,
      ...brandBlock,
    ].join('\n')
  : format === 'svg'
  ? [
      req.CONTENT,
      '',
      'Author ONE self-contained animated SVG and write it to `out.svg`. Do not render and do not write index.html.',
      ...opening,
      form,
      ...vocab,
      sceneLine,
      styleLine,
      'Use a ' + width + 'x' + height + ' (' + (a.ASPECT || '4:5') + ') viewBox.',
      'Animate with CSS @keyframes inside a <style> element, or with SMIL; no external stylesheet, no script, no network. Reveal a few elements in sequence, each held long enough to read.',
      'Reference the brand typefaces by name with a system fallback, and keep the file well-formed XML with every animated element ending visible.',
      ...tail,
      ...brandBlock,
    ].join('\n')
  : [
      req.CONTENT,
      '',
      ...(isIteration ? opening : [planLine]),
      form,
      ...vocab,
      sceneLine,
      styleLine,
      'Render a ' + width + 'x' + height + ' (' + (a.ASPECT || '4:5') + ') composition that runs about ' + seconds + ' seconds.',
      sampling,
      ...tail,
      ...brandBlock,
    ].join('\n');
const pairedFormat = isDeck ? (a.PAIRED_FORMAT || 'mp4') : '';
return [{ json: Object.assign({}, a, {
  FORCE: force, SCENES: scenes, STYLE: brand.STYLE,
  FORMAT: format, FPS: rate, WIDTH: width, HEIGHT: height, FRAMES: frames, DURATION_SECONDS: seconds, RATE: rate,
  SESSION_ID: sessionId,
  AUTHOR_URL: base ? base + '/v1/chat/completions' : '',
  ARTIFACT_URL: base ? base + '/artifacts/' + sessionId + '/out.' + format : '',
  PAIRED_FORMAT: pairedFormat,
  PAIRED_ARTIFACT_URL: (isDeck && base) ? base + '/artifacts/' + sessionId + '/out.' + pairedFormat : '',
  AUTHOR_BODY: JSON.stringify({ messages: [{ role: 'user', content: brief }], session_id: sessionId, format: format, fps: rate, width: width, frames: frames, durationSeconds: seconds }),
}) }];

// The rendered artifact the session returned, as the asset, plus the composer's own
// report kept as STORYBOARD so a bad visual is diagnosable from the run record. Read
// the bytes with getBinaryDataBuffer: this instance keeps binaries out of band, so
// binary.data is a reference ("database:<id>"), not the base64. The workflow never
// sees the agent's composition markup, only this file. A deck run yields two files
// in one turn - the deck and its paired video - so it returns two assets.
const a = $('build_author_brief').first().json;
const item = $input.first();
const out = item.json || {};
const binMeta = (item.binary && item.binary.data) || null;
const report = (() => {
  try {
    const resp = $('execute_author').first().json || {};
    const msg = resp.choices && resp.choices[0] && resp.choices[0].message;
    const content = msg && msg.content;
    return typeof content === 'string' ? content.slice(0, 6000) : '';
  } catch (e) { return ''; }
})();
const base = {
  ASSET_TYPE: a.ASSET_TYPE, RENDER_MODE: a.RENDER_MODE || '', FORMAT: a.FORMAT || '',
  STATUS: '', PROMPT: '', CONTENT_TYPE: '', ERROR: '', STORYBOARD: report,
  DURATION_MS: String(Math.round((Number(a.DURATION_SECONDS) || 0) * 1000)),
  FRAME_COUNT: String(Number(a.FRAMES) || ''), WIDTH: a.WIDTH || '', HEIGHT: a.HEIGHT || '',
  IMAGE: '',
};
const describe = (v, fallback) => {
  if (typeof v === 'string' && v) return v;
  if (v && typeof v === 'object' && typeof v.message === 'string') return v.message;
  if (v != null) return JSON.stringify(v);
  return fallback;
};
if (!a.AUTHOR_URL) {
  return [{ json: Object.assign({}, base, { STATUS: 'ERROR', ERROR: 'PI_RENDER_URL is not configured' }) }];
}
if (!binMeta) {
  const reason = describe(out.error || out.message, 'agent authoring returned no artifact').slice(0, 500);
  return [{ json: Object.assign({}, base, { STATUS: 'ERROR', ERROR: reason }) }];
}
const mime = binMeta.mimeType || 'image/gif';
const buffer = await this.helpers.getBinaryDataBuffer(0, 'data');
const items = [Object.assign({}, base, {
  STATUS: 'RENDERED', CONTENT_TYPE: mime, IMAGE: 'data:' + mime + ';base64,' + buffer.toString('base64'),
})];
// A deck's paired video arrives on the same item as `paired`, fetched after the deck.
const pairedMeta = item.binary && item.binary.paired;
if (pairedMeta) {
  const pairedMime = pairedMeta.mimeType || 'video/mp4';
  const pairedBuffer = await this.helpers.getBinaryDataBuffer(0, 'paired');
  items.push(Object.assign({}, base, {
    ASSET_TYPE: a.PAIRED_ASSET_TYPE || (a.ASSET_TYPE + '_video'),
    RENDER_MODE: 'video', FORMAT: a.PAIRED_FORMAT || 'mp4', PAIRED_OF: a.ASSET_TYPE,
    STATUS: 'RENDERED', CONTENT_TYPE: pairedMime,
    IMAGE: 'data:' + pairedMime + ';base64,' + pairedBuffer.toString('base64'),
  }));
}
return items.map((json) => ({ json }));

// The brand, read once from datasets/brand.json (the only copy), resolved to the
// requested scheme and shaped for its two consumers: the authoring brief for the
// composer and the raster prompt. This node also owns the STYLE check, because the
// scheme names are data here and nowhere else, so an unknown STYLE fails naming it.
const raw = $('download_brand').first().json.output || '{}';
let b;
try {
  b = JSON.parse(raw);
} catch (e) {
  throw new Error('datasets/brand.json is not valid JSON: ' + e.message);
}
const req = $('normalize_input').first().json;
const schemeName = String(req.STYLE || b.defaultScheme || '');
const scheme = b.schemes && b.schemes[schemeName];
if (!scheme) throw new Error('unknown STYLE: ' + schemeName + ' (brand declares: ' + Object.keys(b.schemes || {}).join(', ') + ')');
const typo = b.typography || {};
const BRAND = [
  'Brand palette (' + schemeName + ' scheme, use only these roles):',
  'background ' + scheme.shell + ', text ' + scheme.ink + ', muted text ' + scheme.inkMuted + ',',
  'accent ' + scheme.accent + ', accent-strong ' + scheme.accentStrong + ', accent-deep ' + scheme.accentDeep + '.',
  'Typefaces: ' + typo.text + ' for text, ' + typo.code + ' for code.',
].join('\n');
return [{ json: {
  STYLE: schemeName,
  BRAND,
  ART_DIRECTION: String((b.photographic || {}).artDirection || ''),
} }];

// prompts/visual_motion_rules.md is the one copy of the motion grammar. It is
// fetched once and handed to build_author_brief, which appends it to every brief.
return [{ json: { RULES: String($json.output || '') } }];

// prompts/visual_forms.md is the one copy of the form vocabulary. It is fetched
// once and handed to build_author_brief, which appends it to every brief.
return [{ json: { FORMS: String($json.output || '') } }];

// One item per rendered asset, with the base64 data URL turned into binary so the S3
// node can upload it, and the object key the run row will carry instead of the bytes.
// The prune lists the prefix 'visual-studio/' and the S3 node's file:getAll sets a '/'
// delimiter, so the key must not add another one: with the prefix left as
// 'visual-studio' the key's own slash makes it a CommonPrefix and it is never listed.
// A run where every asset failed has nothing to store and returns none.
const items = $('merge_branches').all().map((i) => i.json);
const runId = String($('normalize_input').first().json.RUN_ID || '').replace(/[^A-Za-z0-9_-]/g, '');
const EXT = { 'video/mp4': 'mp4', 'image/gif': 'gif', 'image/webp': 'webp', 'image/png': 'png',
              'image/svg+xml': 'svg', 'text/html': 'html' };
const out = [];
for (const a of items) {
  const url = String(a.IMAGE || '');
  const comma = url.indexOf(',');
  if (!url.startsWith('data:') || comma < 0) continue;
  const mime = url.slice(5, url.indexOf(';', 5));
  const ext = EXT[mime] || 'bin';
  const name = String(a.ASSET_TYPE || 'asset').replace(/[^A-Za-z0-9._-]/g, '');
  const key = 'visual-studio/' + runId + '-' + name + '.' + ext;
  const buffer = Buffer.from(url.slice(comma + 1), 'base64');
  out.push({
    json: { S3_KEY: key, S3_BYTES: buffer.length, CONTENT_TYPE: mime, ASSET_TYPE: a.ASSET_TYPE },
    binary: { data: await this.helpers.prepareBinaryData(buffer, key, mime) },
  });
}
return out;
